    var connectedTitle = selected === 'netlify' ? t('Netlify is connected', 'Netlify подключён') : (selected === 'cloudflare' ? t('Cloudflare Pages is connected', 'Cloudflare Pages подключён') : t('Connection verified', 'Подключение проверено'));
